def transform(grid):
    h, w = len(grid), len(grid[0])
    row_seps = [r for r in range(h) if all(v == 8 for v in grid[r])]
    col_seps = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    rb = [-1] + row_seps + [h]
    cb = [-1] + col_seps + [w]
    rr = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    cr = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    marks = []
    for tr, (r0, r1) in enumerate(rr):
        for tc, (c0, c1) in enumerate(cr):
            for r in range(r0, r1):
                for c in range(c0, c1):
                    if grid[r][c] not in (0, 8):
                        marks.append((tr, tc, grid[r][c]))
    out = [row[:] for row in grid]
    painted = {}
    def paint(tr, tc, color):
        key = (tr, tc)
        if key in painted and painted[key] != color:
            painted[key] = 6
        else:
            painted[key] = color
    for color in {m[2] for m in marks}:
        same = [(r, c) for r, c, v in marks if v == color]
        # Join aligned markers, filling only the span between endpoints.
        for r in range(len(rr)):
            cols = sorted(c for mr, c in same if mr == r)
            for a, b in zip(cols, cols[1:]):
                for c in range(a, b + 1):
                    paint(r, c, color)
        for c in range(len(cr)):
            rows = sorted(r for r, mc in same if mc == c)
            for a, b in zip(rows, rows[1:]):
                for r in range(a, b + 1):
                    paint(r, c, color)
    for (tr, tc), color in painted.items():
        r0, r1 = rr[tr]
        c0, c1 = cr[tc]
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = color
    return out

